INSERT INTO faqs (question, answer, sort_order) VALUES
  ('How far ahead should I order?', 'For custom cakes, please order at least 48 hours ahead, and 2 to 4 weeks ahead for wedding cakes. Small chops and pastries can often be done sooner, so just ask.', 0),
  ('Do you deliver?', 'Yes, we deliver across the city. The delivery fee depends on your location and is confirmed with your order.', 1),
  ('How do I pay?', 'We confirm your order with a deposit, and the balance is paid before pickup or delivery. Pay only to our official account.', 2),
  ('Can you copy a design I saw online?', 'Yes. Send us the picture with your order and we''ll recreate it or adapt it to your taste and budget.', 3),
  ('Do you make eggless or sugar-free cakes?', 'Tell us your dietary needs when you order and we''ll let you know what we can make.', 4);
